import{r as e}from"../../../../rolldown-runtime-kx061hj1.js";import{Zp as t,em as n}from"../../../../content-de-meta-ee5tgx76.js";import{u as r}from"../../../../WidgetCopy-b0lgde76.js";import{i,n as a,r as o,t as s}from"../../../../UseCaseFilm-nu5q16ek.js";var c=e(n(),1),l=t(),{I:u,esc:d}=o,{ICON:f}=i,p=f.doc,m="Research memo - Norwell indemnity tender.docx",h=u.globe,g=u.folder,_=(e,t)=>a.outlookMsg({cls:e,style:t,logo:"",account:"daniel.okafor@ashgrovemed.com",unread:7,folder:"Inbox",from:{name:"Maya Lindqvist",email:"maya.lindqvist@ashgrovemed.com"},to:"Daniel Okafor",subject:"Norwell won’t pick up our defense on the Dorsey claim: do we have to fund this ourselves?",time:"Mon 8/24/2026 9:14 AM",list:[["Maya Lindqvist","Norwell won’t pick up our defense on the Dorsey claim","Dan, Norwell’s carrier wrote back Friday refusing our tender.","9:14 AM"],["Contracts intake","New request: Halvorsen Robotics reseller agreement","Submitted by Priya Nair (Sales Ops). Requested turnaround","8:51 AM"],["Owen Park","Re: Board consent, Series C secondary","Signed pages attached. I’ll hold the originals until","8:07 AM"],["DocuSign","Completed: Brightline Logistics MSA amendment 2","All parties have signed. You can view the completed","Yesterday"],["Rina Castellanos","Dorsey v. Ashgrove: scheduling order","Response now due September 12. Calendar invite to follow for","Yesterday"]],bodyHtml:'<p>Dan,</p><p>Norwell’s carrier wrote back Friday refusing our tender. They say they only owe us anything if Norwell is found negligent, and that the clause doesn’t cover us where the complaint says we were also at fault.</p><p>Our response in the Dorsey case is due Sept 12. Can you tell me where we stand by Thursday? MSA and the complaint attached.</p><p>Maya</p><p style="color:#666;font-size:13px">Maya Lindqvist · VP Operations · Ashgrove Medical Devices, Inc.</p>',attachments:[{name:"Norwell MSA (executed 2024).pdf",size:"412 KB",icon:u.pdf},{name:"Dorsey complaint.pdf",size:"1.1 MB",icon:u.pdf}]}),v=e=>`<span class="tg">[${e}]</span>`,y=`<div class="dg doc-memo"><div class="rh"><span>Privileged &amp; Confidential · Attorney Work Product</span><span>Draft 1 · not for distribution</span></div>
<div class="mh">Memorandum</div>
<table class="cap"><tr><td>To</td><td>Maya Lindqvist, VP Operations</td></tr><tr><td>From</td><td>Daniel Okafor, Senior Counsel, Commercial (draft)</td></tr><tr><td>Date</td><td>August 28, 2026</td></tr><tr><td>Re</td><td>Norwell Facilities Services, tender of defense and indemnity in <i>Dorsey v. Ashgrove Medical Devices, Inc.</i>, No. 26-CV-04418 (Colum. Super. Ct.)</td></tr></table>
<h2><em>I.</em>Questions presented</h2><ol class="qp"><li>Under Franklin law, which governs the MSA (§ 14.3), does § 9.2 oblige Norwell to assume Ashgrove’s defense of the <i>Dorsey</i> action upon tender, before any finding that Norwell was negligent?</li><li>Does § 9.2 require Norwell to indemnify Ashgrove for any share of a judgment attributed to Ashgrove’s own negligence?</li></ol>
<h2 class="sa"><em>II.</em>Short answers</h2>
<p class="sa1"><b class="hold">1. Yes, most likely.</b> A promise to “defend, indemnify and hold harmless” carries a duty to defend that arises when a covered claim is tendered, not when fault is later determined. Fr. Civ. Code § 2778(4) ${v("CoCounsel")}; <i>Crane v. Wexford Constr. Co.</i>, 41 Fr. 4th 512, 521–23 (2011) ${v("CoCounsel")} (the duty is triggered by tender of a claim “embraced by the indemnity,” whether or not the indemnitor is ultimately found negligent). The <i>Dorsey</i> complaint pleads injuries “arising out of” Norwell’s floor-care services (Compl. ¶¶ 14–19) ${v("user provided")}, which places it within § 9.2 as written. Norwell’s refusal is a present breach, and Ashgrove’s reasonable defense costs from the July 31 tender forward are recoverable as damages. <i>Pell Logistics, Inc. v. Sandor Prop. Mgmt., LLC</i>, 102 Fr. App. 3d 77, 85–86 (2019) ${v("CoCounsel")}; see 2023 memo re Bayline Security tender, Part II ${v("iManage, prior memo")}.</p>
<p><b class="hold">2. Not in full.</b> Franklin applies the express-negligence rule: an indemnitee recovers for its own active negligence only where the clause says so in specific terms, and general “any and all claims … arising out of or relating to” language does not. <i>Harrow v. Delacroix Indus., Inc.</i>, 88 Fr. App. 3d 240, 247–49 (2016) ${v("CoCounsel")}. Ashgrove still recovers for Norwell’s share and for passive negligence such as failure to discover the hazard, <i>Minton v. Carroway Foods Co.</i>, 95 Fr. App. 3d 610, 618 (2018) ${v("CoCounsel")}; whether the signage allegation is active or passive is Open Issue 2.</p>
<h2><em>III.</em>Facts (as provided)</h2><p>Ashgrove engaged Norwell for floor care at the Brookline distribution center under the 2024 MSA (§§ 9–10 indemnity; § 14.3 Franklin law). On July 2, 2026 a visitor slipped in a corridor Norwell had serviced that morning; the <i>Dorsey</i> complaint names Ashgrove only and alleges wet flooring and missing signage. Ashgrove tendered on July 31; Norwell’s carrier declined on August 21.</p>
<h2><em>IV.</em>Discussion</h2><table class="toc"><tr><td>A.</td><td>Norwell’s duty to defend arose on tender</td><td>1. Fr. Civ. Code § 2778 · 2. Franklin Supreme Court · 3. Court of Appeal, incl. <i>Oakhurst Devs. v. Trilane Elec.</i>, 76 Fr. App. 3d 1002 (2014), distinguished</td></tr><tr><td>B.</td><td>Indemnity for Ashgrove’s own negligence</td><td>1. The express-negligence rule · 2. Active and passive negligence on these facts · 3. The carrier’s obligations on tender, Fr. Admin. Code tit. 12, § 410.7 and Ins. Comm’r Bulletin 2020-3</td></tr><tr><td>C.</td><td>The anti-indemnity statute</td><td>Unresolved; see Open Issue 1</td></tr></table>
<h2 class="oi"><em>V.</em>Open issues</h2>
<p class="oi1"><b class="hold">1. Anti-indemnity statute.</b> Fr. Civ. Code § 2790 ${v("CoCounsel")} voids provisions in “construction contracts” that indemnify a party against its own active negligence. Whether a recurring facilities-services agreement is a construction contract for this purpose is unsettled: the search returned the statute and one unpublished trial-court order, <i>Redfern v. Castellan Bldg. Servs.</i>, No. 22-CV-1187 (Fr. Super. Ct. Mar. 4, 2024) ${v("CoCounsel, unpublished; not citable, Fr. R. Ct. 9.402")}, and no appellate authority. Per your instruction this point was not supplemented from web or model sources. <span class="cn">[CITE NEEDED: resolve before relying on Part II.A; if § 2790 applies, Short Answer 2 stands but the route to it changes.]</span></p>
<p><b class="hold">2. Active or passive.</b> Turns on who owned signage under SOW Ex. B, which is not in the folder ${v("VERIFY: SOW allocates signage to Vendor")}.</p><p><b class="hold">3. Fee recovery procedure</b> in the Columbia court is not analyzed; Franklin law governs substance only (§ 14.3).</p><p><b class="hold">4. Carrier response clock.</b> Tit. 12, § 410.7(b) requires a written acceptance or denial stating grounds within forty days of tender; July 31 + 40 days = September 9, 2026 ${v("VERIFY: tender date from carrier letter")}.</p>
<div class="dn"><b>Drafting notes for the reviewing attorney</b>Citations found: 13. 10 [CoCounsel] (5 cases, 2 statutes, 1 regulation, 1 bulletin, 1 unpublished order), 2 [iManage, prior memo], 1 [user provided]; 0 from model knowledge; 1 [CITE NEEDED], 2 [VERIFY]. All authorities need a currency check before the memo is sent. Draft only.</div></div>`,b=(e,t)=>a.word({cls:e,style:t,file:m,bodyHtml:y}),x=[u.folder,g,h,h],S=[0,15300,16100,16900,18700,20500,21400],C=[u.folder,p,p];function w(e){let t=e.seq("question.option");return{id:"legalmemo",tone:"plum",title:e("title"),sub:e("sub"),lines:{ask:e("line.ask"),does:e("line.does"),question:e("line.question"),get:e("line.get"),note1:e("line.note1"),note2:e("line.note2"),again:e("line.again"),close:e("line.close")},exampleNouns:["Norwell","Dorsey","Ashgrove","Franklin","CoCounsel","iManage","Thomson","docx","Lindqvist","indemnity"],opener:{mark:e("opener.mark"),to:"none",html:_("opx","")},connectors:[],attachments:e.keys("attachment",".title").map((t,n)=>({title:e(`${t}.title`),sub:e(`${t}.sub`),tagIcon:C[n]??u.doc,tag:e(`${t}.tag`)})),skill:{section:"Litigation Legal",items:["brief-section-drafter","chronology","matter-briefing"],pick:0},placeholder2:e("placeholder"),prompt:e("prompt"),sources:e.keys("source",".text").map((t,n)=>({logo:x[n]??u.doc,verb:e(`${t}.verb`),text:e(`${t}.text`)})),verbs:e.seq("verb").map((e,t)=>[S[t]??S[S.length-1],e]),question:{title:e("question.title"),options:t,pick:0,answer:e("question.answer")},reply:{did:e.seq("reply.did"),text:e("reply.text"),files:[{icon:"doc",name:m,meta:e("file1.meta")}]},apps:[{cls:"wd1",marks:[{at:e("line.note1.at1"),kind:"arrow",target:e=>e.querySelector(".wd1 .tg")||e.querySelector(".wd1 p.sa1")}],html:b,target:e=>e.querySelector(".wd1 p.sa1"),dimPad:[12,8],dimR:8,notePos:[150,150]},{cls:"wd2",same:!0,marks:[{at:e("line.note2.at1"),kind:"arrow",target:e=>e.querySelector(".wd1 h2.oi")||e.querySelector(".wd2 h2.oi")},{at:e("line.note2.at2"),kind:"bracket",target:e=>{let t=e.querySelector(".wd1 h2.oi")||e.querySelector(".wd2 h2.oi");if(!t)return null;let n=[],r=t.nextElementSibling;for(;r&&n.length<4&&(r.className||"").startsWith("oi");)n.push(r),r=r.nextElementSibling;return n.length?[n[0],n[n.length-1]]:t}}],html:b,target:e=>e.querySelector(".wd2 p.oi1"),dimPad:[12,8],dimR:8,notePos:[150,150]}],again:{kind:"skill",bubbleHtml:d(e.pattern("again.bubble")).replace("{when}",`<span class="ph2 sch">${d(e("again.bubble.when"))}</span>`),underlineWord:e("again.underline"),card:{name:"research-memo",line:e("again.card.line"),reads:[{logo:u.folder,name:"Working folder"},{logo:h,name:"CoCounsel Legal"},{logo:g,name:"iManage"}],shared:e("again.card.shared")}}}}function T(){let e=r(),t=(0,c.useMemo)(()=>w(e),[e]);return(0,l.jsx)(s,{spec:t})}export{T as default};